query networkConfigSnmpSiteSettings ( $accountId:ID! $siteRefInput:SiteRefInput!) {
	networkConfig ( accountId:$accountId ) {
		snmp {
			siteSettings ( input:$siteRefInput   ) {
				site {
					id
					name
				}
				profile {
					id
					name
				}
				enabled
				audit {
					updatedTime
					updatedBy {
						id
						name
					}
				}
			}
		}
	}	
}
